/*
 * A209166  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A209167; see the Formula section.
 * https://oeis.org/A209166
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the n‑th entry of the flattened triangle formed by the
 *            coefficients of the polynomials u(n,x) generated by u(n,x) =
 *            u(n‑1,x) + (x+1)*v(n‑1,x) v(n,x) = (x+1)*u(n‑1,x) + x*v(n‑1,x) +
 *            1 with u(1,x)=1, v(1,x)=1. The rows are emitted in order: row 1,
 *            row 2, … and this function returns the n‑th...
 * Range:     u8 n <= 24, u16 n <= 56, u32 n <= 56, u64 n <= 56, u128 n <= 56,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>   /* for size_t */

#define MAX_ROW 200  /* sufficient for n up to 100000, far beyond the needed 10 000 */

seq_t a(idx_t n)
{
    if (n <= 1)                     /* a(1) == 1 */
        return (seq_t)1;

    /* Find the row r such that r(r+1)/2 ≥ n */
    idx_t r = 1;
    while ((r * (r + 1) / 2) < n)
        ++r;

    /* Number of terms before this row and column index (0‑based) */
    idx_t prev = (r - 1) * r / 2;
    idx_t col   = n - prev - 1;      /* 0 ≤ col < r */

    /* Trivial bounds check for safety in extreme builds */
    if (r > MAX_ROW) return (seq_t)0;

    /* Working arrays – all on the stack to avoid constructor issues */
    seq_t u[MAX_ROW], v[MAX_ROW];
    seq_t u_mul[MAX_ROW], v_mul[MAX_ROW];
    seq_t new_u[MAX_ROW], new_v[MAX_ROW];

    /* Initial row (row 1) */
    u[0] = (seq_t)1;
    v[0] = (seq_t)1;

    /* Build rows 2 … r */
    for (idx_t row = 2; row <= r; ++row) {
        idx_t sz = row;  /* new row length */

        /* Compute (x+1)*u and (x+1)*v */
        u_mul[0] = u[0];
        v_mul[0] = v[0];
        for (idx_t k = 1; k < sz - 1; ++k) {
            u_mul[k] = u[k] + u[k - 1];
            v_mul[k] = v[k] + v[k - 1];
        }
        u_mul[sz - 1] = u[sz - 2];
        v_mul[sz - 1] = v[sz - 2];

        /* Compute new_u = u + (x+1)*v */
        new_u[0] = u[0] + v_mul[0];
        for (idx_t k = 1; k < sz - 1; ++k)
            new_u[k] = u[k] + v_mul[k];
        new_u[sz - 1] = v_mul[sz - 1];  /* last coefficient */

        /* Compute new_v = (x+1)*u + x*v + 1 */
        new_v[0] = u_mul[0] + (seq_t)1;
        for (idx_t k = 1; k < sz - 1; ++k)
            new_v[k] = u_mul[k] + v[k - 1];
        new_v[sz - 1] = u_mul[sz - 1] + v[sz - 2];

        /* Copy results back for next iteration */
        for (idx_t k = 0; k < sz; ++k) {
            u[k] = new_u[k];
            v[k] = new_v[k];
        }
    }

    /* The requested coefficient in the final row */
    return u[col];
}
